"""CPU-only functional trace acceptance; keeps CUDA completeness and fault evidence separate."""
import argparse,collections,fcntl,hashlib,importlib.util,json,sqlite3,sys
from pathlib import Path
P=Path(__file__).resolve().parent;D=P/'tiny-diagnostic-v1';sys.path.insert(0,str(P));import tiny_diagnostic as tiny
def read(p):return json.loads(Path(p).read_text())
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def run(stage):
 out=D/stage;sql=out/'trace.sqlite';db=sqlite3.connect('file:'+str(sql)+'?mode=ro',uri=True);db.row_factory=sqlite3.Row;tables={x[0]for x in db.execute("SELECT name FROM sqlite_master WHERE type='table'")};strings=dict(db.execute('SELECT id,value FROM StringIds'));nv=[dict(x)for x in db.execute('SELECT * FROM NVTX_EVENTS')];runtime=[dict(x)for x in db.execute('SELECT * FROM CUPTI_ACTIVITY_KIND_RUNTIME')];diag=[dict(x)for x in db.execute('SELECT * FROM DIAGNOSTIC_EVENT')]
 name=lambda x:x.get('text')or strings.get(x.get('textId'));queries=sorted([x for x in nv if name(x)=='Chimera/query_local_row'],key=lambda x:x['int64Value']);assert len(queries)==32 and[x['int64Value']for x in queries]==list(range(32));assert len({x['globalTid']for x in queries})==1
 outside=[x for x in runtime if not any(q['start']<=x['start']<=x['end']<=q['end']for q in queries)];assert all(strings[x['nameId']]=='cuProfilerStart'for x in outside)and len(outside)==1
 parser=P.parent/'observation/parse_khat.py';spec=importlib.util.spec_from_file_location('khat_frozen_existing',parser);m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m);khat=m.parse(m.load_sqlite(sql),400);assert len(khat['queries'])==32 and khat['total_Khat']==12800 and all(x['actual_chunks']==1 and x['actual_fullbit_per_chunk']==[400]for x in khat['queries'])
 names=collections.Counter(name(x)for x in nv)
 for n in ['Chimera/candidate_generation','Chimera/candidate_refinement','Chimera/candidate_generation_refinement']:assert names[n]==32
 comparison=tiny.compare('observation',stage);tree=read(out/'tree-supervision.json');leaf=read(out/'leaf-lease.json');assert tree['returncode']==0 and tree['all_owned_descendants_gone']and not tree['timed_out'];pids=[read(out/'process.json')['pid'],leaf['pid'],*[r['pid']for r in tree['reaped']]];absent={str(pid):not Path(f'/proc/{pid}').exists()for pid in pids};assert all(absent.values())
 with open(out/'diagnostic-output.lock','a')as f:fcntl.flock(f,fcntl.LOCK_EX|fcntl.LOCK_NB)
 from run_search_grid_v2 import check,check_thread_info,pagefault_evidence
 from search_modes_v2 import verify_mode_log
 plan=read(D/'plan.json');output=check(out/'rows.tsv',D/'gt32.npy',32,10000,100);output={k:v for k,v in output.items()if k not in ['qps','mean_ms','p50_ms','p99_ms']};omp=check_thread_info(out/'output.log',plan['environment']);mode=verify_mode_log(out/'output.log',dict(algorithm_variant='full',kernel_mode='full'));fault=pagefault_evidence(out/'output.log')
 kernels={n:db.execute('SELECT COUNT(*) FROM '+n).fetchone()[0]for n in tables if n.startswith('CUPTI_ACTIVITY_KIND')and'KERNEL'in n};memcpy=db.execute('SELECT COUNT(*) FROM CUPTI_ACTIVITY_KIND_MEMCPY').fetchone()[0];warnings=[x for x in diag if x['severity']>1];launches=collections.Counter(strings[x['nameId']]for x in runtime if'LaunchKernel'in strings[x['nameId']]);kernel_timestamps_complete=bool(kernels)and sum(kernels.values())>0 and not any('incomplete CUPTI events dropped'in x['text']and not' dropped: 0.'in x['text']for x in diag)
 receipt=dict(status='PASS_TINY_NVTX_OUTPUT_COUNTS_AND_SUPERVISION_FUNCTIONAL_SCOPE',GPU_used_for_postprocess=False,NSYS_capture_scope='offline cohort tiny diagnostic; independent output lock; global lock belongs to coarse guardian',performance_claim=False,formal_profile_accepted=False,ordered_ID_F32_comparison=comparison,output_contract=output,OMP=omp,actual_mode=mode,pagefaults=fault,query_major_faults_actual=fault['query_loop']['major_delta'],captured_query_ranges=32,query_INT64_payloads=list(range(32)),original_prefix_query_rows=list(range(32)),all_runtime_calls_inside_queries_except_cuProfilerStart=True,load_warmup_not_in_CUDA_runtime_capture=True,NVTX_counts=dict(names),Khat_total=khat['total_Khat'],Khat_per_query=[400]*32,actual_chunks_per_query=[1]*32,INT64_SQLite_parser_compatible=True,existing_parser_sha256=sha(parser),CUDA_kernel_tables=kernels,CUDA_runtime_launch_counts=dict(launches),CUDA_memcpy_rows=memcpy,CUDA_kernel_timestamps_complete=kernel_timestamps_complete,CUDA_complete_trace_accepted=False,diagnostic_events=diag,diagnostic_warnings=warnings,all_guard_leaf_reaped_pids_absent=absent,independent_output_lock_released=True,tree_lease_transfers=tree['lease_transfers'],trace_sha256=sha(out/'trace.nsys-rep'),SQLite_sha256=sha(sql),postprocessor_sha256=sha(__file__),QA_acceptance_sha256=sha(D/'QA-acceptance.json'),cohort_source_freeze_sha256=sha(D/'freeze.json'),formal_profile_freeze_sha256=sha(P/'freeze.json'))
 for n,v in [('postprocess-Khat.json',khat),('postprocess-acceptance.json',receipt)]:
  with open(out/n,'x')as f:json.dump(v,f,indent=2);f.write('\n')
 with open(out/'postprocess-evidence-SHA.json','x')as f:json.dump({n:sha(out/n)for n in ['postprocess-Khat.json','postprocess-acceptance.json','tree-supervision.json','leaf-lease.json','output.log']},f,indent=2)
 print(json.dumps(dict(stage=stage,status=receipt['status'],query_major_faults=receipt['query_major_faults_actual'],Khat=12800,kernel_tables=kernels,CUDA_complete_trace_accepted=False,acceptance_sha256=sha(out/'postprocess-acceptance.json'))))
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('stage',choices=['nsys32','nsys32-sw']);run(p.parse_args().stage)
